        emon.Testport.AssertEq(HtRun(cg, refs, fw, fl, et, feats, ow, nfw, nfl, fv, fx, afa), 2, "two groups decided");
        emon.Testport.AssertEq(Player.FwCount(nfw), 2, "both stay");
        emon.Testport.AssertEq(Player.FvGet(fv, 0, 2), 301, "rule 301");
        emon.Testport.AssertEq(Player.FvGet(fv, 0, 3), 600, "confidence 600");
        emon.Testport.AssertEq(emon.Port.CellsAt(nfw, 23), 2, "src hidden-text alone");
        emon.Testport.AssertEq(Player.FaCount(afa), 0, "nothing set aside");
    }
}
